effect.shader:
void main() {
vec2 uv = acScreenNorm;
vec4 src = texture2DCv(inputImg.texture, uv);
vec3 c = src.rgb + liftColor.rgb;
c = max(c, vec3(0.0));
c = pow(c, vec3(1.0 / max(gamma, 0.001)));
c = c * gainColor.rgb;
vec3 outRgb = mix(src.rgb, clamp(c, vec3(0.0), vec3(1.0)), mix);
gl_FragColor = vec4(outRgb, src.a);
}
